    const name = [row.first_name, row.last_name].filter(Boolean).join(' ').trim() || 'Digital business card';
    const role = [row.title, row.company].filter(Boolean).join(' · ');
    const title = name + (role ? ' | ' + role : '');
    const desc = (role ? role + '. ' : '') + 'Save my contact, call, WhatsApp or email in one tap.';
    const og = String((row.extras && row.extras.og_image) || ''), ph = String(row.photo_url || '');
    const img = /^https:\/\/[^\s"<>]+\.jpg$/i.test(og) ? og : /^https:\/\/[^\s"<>]+\.(jpe?g|png|webp)(\?|$)/i.test(ph) ? ph : OG_IMG;
    const link = 'https://card.nexbizrise.com' + (row.public_id ? '/c/' + row.public_id : '/' + row.slug);
    const tags = '<meta name="description" content="' + esc(desc) + '"><link rel="canonical" href="' + esc(link) + '"><meta property="og:type" content="profile"><meta property="og:site_name" content="NexBizRise"><meta property="og:title" content="' + esc(title) + '"><meta property="og:description" content="' + esc(desc) + '"><meta property="og:url" content="' + esc(link) + '"><meta property="og:image" content="' + esc(img) + '">' + (img === og ? '<meta property="og:image:type" content="image/jpeg"><meta property="og:image:width" content="600"><meta property="og:image:height" content="600">' : '') + '<meta property="og:image:alt" content="' + esc(name) + '"><meta name="twitter:card" content="' + (img === OG_IMG ? 'summary_large_image' : 'summary') + '"><meta name="twitter:title" content="' + esc(title) + '"><meta name="twitter:description" content="' + esc(desc) + '"><meta name="twitter:image" content="' + esc(img) + '">';
    const drop = { element(e) { e.remove(); } };
    return new HTMLRewriter()
      .on('head meta[property^="og:"]', drop).on('head meta[property^="og:image:"]', drop).on('head meta[name^="twitter:"]', drop).on('head meta[name="description"]', drop).on('head link[rel="canonical"]', drop)
      .on('title', { element(e) { e.setInnerContent(title); } })
      .on('head', { element(e) { e.append(tags, { html: true }); } })
