  const r = await fetch('https://api.cloudflare.com/client/v4/accounts/' + env.CF_ACCOUNT_ID + '/analytics_engine/sql', { method: 'POST', headers: { authorization: 'Bearer ' + env.CF_API_TOKEN }, body: q });
